  values ('ME', 'short_answer', 'What is conditioning of fish before stocking/transfer and/or transportation? What are the five major reasons for conditioning of fish before stocking/transfer and/or transportation? (6 marks)', 'Conditioning means holding fish in clean, well-aerated water without feeding for 24-48 hours before handling, so they empty their gut and get used to crowding. Reasons: (1) empty gut, so less faeces and ammonia foul the transport water; (2) lower oxygen consumption during transport; (3) less stress and mortality; (4) fish become hardy and used to handling and crowding; (5) weak, injured or diseased fish can be removed before stocking.', null, '[{"point": "Definition: holding fish in clean water without feed for a period to empty the gut and acclimatise", "marks": 1}, {"point": "Five reasons, 1 mark each: empty gut, less ammonia/CO₂ and oxygen use, less stress and injury, adapt to handling/crowding and water quality, remove weak/diseased fish", "marks": 5}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
