  values ('ME', 'short_answer', 'What is the "five freedoms" framework of animal welfare? List the five freedoms of animal welfare. (6 marks)', 'The five freedoms (Farm Animal Welfare Council, UK) are the basic standards for the care of animals under human control: (1) freedom from hunger and thirst; (2) freedom from discomfort; (3) freedom from pain, injury and disease; (4) freedom to express normal behaviour; (5) freedom from fear and distress.', null, '[{"point": "Framework: internationally used standard (UK FAWC) for minimum welfare", "marks": 1}, {"point": "Five freedoms, 1 mark each: hunger and thirst; discomfort; pain, injury, disease; to express normal behaviour; fear and distress", "marks": 5}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
