  values ('ME', 'short_answer', 'Define ovariohysterectomy. List three immediate/short-term and two long-term possible post-operative complications of ovariohysterectomy. (6 marks)', 'Ovariohysterectomy (spaying) is the surgical removal of both ovaries and the uterus. Short-term complications: haemorrhage from ovarian or uterine vessels; wound infection, swelling or dehiscence; anaesthetic complications (and seroma, self-trauma). Long-term: urinary incontinence; weight gain/obesity; ovarian remnant syndrome; stump pyometra or granuloma.', null, '[{"point": "Surgical removal of ovaries and uterus (spaying)", "marks": 1}, {"point": "Three short-term: haemorrhage, wound infection/dehiscence, anaesthetic complications/seroma", "marks": 3}, {"point": "Two long-term: urinary incontinence, obesity, ovarian remnant syndrome, stump pyometra", "marks": 2}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
