  values ('ME', 'short_answer', 'Define the bovine estrous cycle and name its four main phases. (6 marks)', 'The bovine estrous cycle is the recurring series of reproductive changes in the cow from one heat to the next, lasting about 21 days (18-24). Phases: proestrus (follicle growth, rising oestrogen); estrus (standing heat, about 12-18 h, ovulation follows); metestrus (corpus luteum forms); diestrus (functional corpus luteum, high progesterone).', null, '[{"point": "Definition: repeated reproductive cycle from one heat to the next, about 21 days (18-24)", "marks": 2}, {"point": "Four phases: proestrus, estrus, metestrus, diestrus", "marks": 4}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
